using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpServer.Tools;

[McpServerToolType]
public sealed class ApiFetchTool
{
    [McpServerTool("fetch_post"), Description("Fetches a post by ID from the external API.")]
    public static async Task<string> FetchPost(
        IHttpClientFactory httpClientFactory,
        [Description("The numeric post ID to retrieve.")] int id)
    {
        var client = httpClientFactory.CreateClient("ExternalApi");
        var post = await client.GetFromJsonAsync<JsonElement>($"posts/{id}");
        return JsonSerializer.Serialize(post, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizePrompt
{
    [McpServerPrompt("summarize"), Description("Generates a prompt to summarize the given text.")]
    public static IList<PromptMessage> Summarize(
        [Description("The text content to summarize.")] string text,
        [Description("Optional desired length: short, medium, or long.")] string? length = "medium")
    {
        return
        [
            new PromptMessage
            {
                Role = Role.User,
                Content = new Content
                {
                    Text = $"Please provide a {length} summary of the following text:\n\n{text}"
                }
            }
        ];
    }
}

